def move_stages(apps, schema_editor):
    """«Propuesta enviada» and «Cambios en la propuesta» become «Propuesta»; studied
    businesses that already have a demo become «Demo lista».

    The stage history (StageChange) is immutable and keeps the old names; these
    moves are not added to it because a migration has no person to sign them.
    """
    from django.core.files.storage import default_storage
    from django.utils import timezone
    Business = apps.get_model('core', 'Business')
    DemoVersion = apps.get_model('core', 'DemoVersion')
    now = timezone.now()
    Business.objects.filter(stage='review').update(stage='proposal', stage_changed_at=now)
    with_versions = set(DemoVersion.objects.values_list('business_id', flat=True))
    for business in Business.objects.filter(stage='profile_created').only('pk'):
        # Before versions a demo was a single file keyed by the primary key.
        if business.pk in with_versions or default_storage.exists(f'demos/{business.pk}.html'):
            Business.objects.filter(pk=business.pk).update(stage='demo_ready', stage_changed_at=now)


